#include <chrono>
#include <ratio>

template <typename X, typename Y> using dura = std::chrono::duration<X, Y>;

static_assert((std::chrono::hours::zero() == std::chrono::nanoseconds::zero()) &&
    (dura<short, std::nano>::zero() == dura<int, std::deci>::zero()) &&
    (dura<short, std::deca>::zero() == dura<long, std::exa>::zero()) &&
    (dura<long, std::atto>::zero().count() == dura<float, std::exa>::zero().count()));

int main() {}
